<?php

namespace Database\Seeders;

use AgentCms\Core\Settings\SettingsStore;
use Carbon\CarbonImmutable;
use Illuminate\Database\Console\Seeds\WithoutModelEvents;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Storage;
use Modules\Media\Models\Media;
use Modules\News\Models\News;
use Modules\Works\Models\Work;

/**
 * generated by agentcms template apply — テンプレート import の fixture parity データ。
 * Static Template のカード / ニュースと同一の内容を CMS 側へ投入する（visual regression 用）。
 * 実行: php artisan db:seed --class=Database\\Seeders\\TemplateContentSeeder
 */
class TemplateContentSeeder extends Seeder
{
    use WithoutModelEvents;

    public function run(): void
    {
        // Site Settings 初期値（テンプレートの og:site_name / description 由来）。
        // ユーザーが設定済みの値は上書きしない
        $settings = app(SettingsStore::class);
        $site = [
            'site_name' => 'Green Leaf Design',
            'seo_description' => 'Green Leaf Design は京都の小さなデザインスタジオです。植物のように育つウェブサイトをつくります。',
            // Phase 8 F-5: layout/hero が settings 駆動になったため、
            // import 元テンプレートの brand 値をここで供給する（e2e の期待値と一致）
            'tagline' => "自然体のデザインで、\nブランドを育てる。",
            // hero の説明文は meta description と別文（import 元の原文を保持 —
            // 折返し行数まで static と一致させる。未設定サイトは seo_description に fallback）
            'hero_text' => 'Green Leaf Design は植物のように育つウェブサイトをつくります。',
            'address' => '京都市左京区0-0-0',
            'tel' => '075-000-0000',
            'contact_email' => 'hello@greenleaf.example',
        ];
        foreach ($site as $key => $value) {
            if (blank($settings->get($key))) {
                $settings->put([$key => $value]);
            }
        }

        $works = [
            ['title' => '花屋のオンラインストア', 'slug' => 'imported-work-1', 'category' => 'EC', 'year' => 2026, 'image' => 'work1.png', 'order' => 0],
            ['title' => '造園会社コーポレート', 'slug' => 'imported-work-2', 'category' => 'Corporate', 'year' => 2025, 'image' => 'work2.png', 'order' => 1],
            ['title' => '植物園イベントLP', 'slug' => 'imported-work-3', 'category' => 'LP', 'year' => 2025, 'image' => 'work3.png', 'order' => 2],
            ['title' => '種苗ブランドサイト', 'slug' => 'imported-work-4', 'category' => 'branding', 'year' => 2024, 'image' => 'work4.png', 'order' => 3],
            ['title' => '盆栽サブスクリプション', 'slug' => 'imported-work-5', 'category' => 'Service', 'year' => 2024, 'image' => 'work5.png', 'order' => 4],
            ['title' => 'ハーブティー パッケージ', 'slug' => 'imported-work-6', 'category' => 'Package', 'year' => 2023, 'image' => 'work6.png', 'order' => 5],
        ];
        foreach ($works as $row) {
            $media = $this->importMedia($row['image']);
            // published_at は「年末（未来なら現在時刻へクランプ）- order 日」:
            // published() スコープ（未来日付を除外）に掛からず、一覧の並び（published_at desc）が
            // テンプレートのカード順と一致する。表示は年のみなので completed_at の年は保たれる
            $base = CarbonImmutable::create($row['year'], 12, 31, 12);
            if ($base->isFuture()) {
                $base = CarbonImmutable::now()->subDay();
            }
            $publishedAt = $base->subDays($row['order']);
            Work::query()->updateOrCreate(['slug' => $row['slug']], [
                'title' => $row['title'],
                'category' => $row['category'],
                'excerpt' => $row['title'],
                'body' => '<p>'.e($row['title']).' の制作実績です。</p>',
                'completed_at' => $publishedAt->toDateString(),
                'status' => 'published',
                'published_at' => $publishedAt,
                'main_image_id' => $media?->id,
                'seo_title' => null,
                'seo_description' => null,
            ]);
        }

        $news = [
            ['title' => '夏季休業のお知らせ', 'slug' => 'imported-news-1', 'date' => '2026-07-01', 'order' => 0],
            ['title' => '実績を更新しました', 'slug' => 'imported-news-2', 'date' => '2026-06-15', 'order' => 1],
            ['title' => 'サイトをリニューアルしました', 'slug' => 'imported-news-3', 'date' => '2026-05-30', 'order' => 2],
        ];
        foreach ($news as $row) {
            News::query()->updateOrCreate(['slug' => $row['slug']], [
                'title' => $row['title'],
                'body' => '<p>'.e($row['title']).'</p>',
                'status' => 'published',
                'published_at' => CarbonImmutable::parse($row['date'])->setTime(12, 0),
                'seo_title' => null,
                'seo_description' => null,
            ]);
        }
    }

    /**
     * database/seeders/template-import/ の画像を Media として取り込む（冪等）。
     * unit テスト時はスキップ（実ストレージを汚さない — DemoContentSeeder と同方針）。
     */
    private function importMedia(string $filename): ?Media
    {
        if (app()->runningUnitTests()) {
            return null;
        }

        $meta = [
            'work1.png' => ['name' => '花屋のオンラインストア', 'alt' => '花屋のオンラインストア'],
            'work2.png' => ['name' => '造園会社コーポレート', 'alt' => '造園会社コーポレート'],
            'work3.png' => ['name' => '植物園イベントLP', 'alt' => '植物園イベントLP'],
            'work4.png' => ['name' => '種苗ブランドサイト', 'alt' => '種苗ブランドサイト'],
            'work5.png' => ['name' => '盆栽サブスクリプション', 'alt' => '盆栽サブスクリプション'],
            'work6.png' => ['name' => 'ハーブティー パッケージ', 'alt' => 'ハーブティー パッケージ'],
        ];
        $name = $meta[$filename]['name'] ?? $filename;
        $alt = $meta[$filename]['alt'] ?? '';

        $existing = Media::query()->firstWhere('name', $name);
        if ($existing !== null) {
            return $existing;
        }

        $sourcePath = database_path('seeders/template-import/'.$filename);
        if (! is_file($sourcePath)) {
            return null;
        }

        $disk = Storage::disk((string) config('agentcms.uploads.disk'));
        $storedPath = 'media/imported-'.$filename;
        $disk->put($storedPath, (string) file_get_contents($sourcePath));
        $dimensions = getimagesize($sourcePath);

        return Media::query()->create([
            'name' => $name,
            'alt' => $alt,
            'path' => $storedPath,
            'mime' => $dimensions !== false ? (string) $dimensions['mime'] : 'image/png',
            'size' => (int) $disk->size($storedPath),
            'width' => $dimensions !== false ? (int) $dimensions[0] : 0,
            'height' => $dimensions !== false ? (int) $dimensions[1] : 0,
            'has_webp' => false,
        ]);
    }
}
